class ReconnectingWebSocket {
  constructor(url, opts = {}) {
    this.url = url;
    this.attempt = 0;
    this.maxDelay = opts.maxDelay || 30000;
    this.baseDelay = opts.baseDelay || 1000;
    this.connect();
  }
  getDelay() {
    const exp = Math.min(this.baseDelay * 2 ** this.attempt, this.maxDelay);
    return exp / 2 + Math.random() * exp / 2; // full jitter
  }
  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onclose = () => {
      const delay = this.getDelay();
      this.attempt++;
      setTimeout(() => this.connect(), delay);
    };
    this.ws.onopen = () => { this.attempt = 0; };
  }
}

import DataLoader from 'dataloader';
// Create per-request dataloader (never share across requests)
const userLoader = new DataLoader(async (userIds) => {
  const users = await db.query('SELECT * FROM users WHERE id IN (?)', [userIds]);
  // Must return results in same order as input ids
  const userMap = new Map(users.map(u => [u.id, u]));
  return userIds.map(id => userMap.get(id) || null);
});
// Now N resolvers = 1 batch query instead of N queries
const user = await userLoader.load(userId);

